-- Example queries:
-- View all active systems:
-- SELECT * FROM system_usage WHERE status = 'active' ORDER BY last_active DESC;

-- View systems inactive for more than 10 minutes:
-- SELECT * FROM system_usage WHERE status = 'active' AND last_active < DATE_SUB(NOW(), INTERVAL 10 MINUTE);

-- Clean up old inactive records (older than 7 days):
-- DELETE FROM system_usage WHERE status = 'inactive' AND last_active < DATE_SUB(NOW(), INTERVAL 7 DAY);

